/// (set by Moonmist's effect for the rest of the turn).
fn is_non_wolf_damage_prevented(state: &GameState, source: ObjectId, registry: &CardRegistry) -> bool {
    if !state.prevent_non_wolf_werewolf_combat_damage {
        return false;
    }
